/**
 * The nightly timer (D16: no new daemon — systemd fires a oneshot `ee backup
 * --scheduled`, which asks the running ee daemon to take the snapshot).
 */
export const BACKUP_SERVICE = 'ee-backup.service'
export const BACKUP_TIMER = 'ee-backup.timer'

export function renderBackupService(nodeBin: string): string {
  return [
    '# Generated by ee. Do not edit.',
    '[Unit]',
    'Description=ee: nightly encrypted backup (plan/phase-backups.md)',
    'After=ee.service',
    'Requires=ee.service',
    '',
    '[Service]',
    'Type=oneshot',
    `ExecStart=${nodeBin} /opt/ee/ee.mjs backup --scheduled`,
    '',
  ].join('\n')
}

/** Daily at hour:minute UTC; Persistent catches a run missed while the box was off. */
export function renderBackupTimer(s: { hour: number; minute: number }): string {
  const hh = String(s.hour).padStart(2, '0')
  const mm = String(s.minute).padStart(2, '0')
  return [
    '# Generated by ee. Do not edit: the schedule is set in Settings → Backups.',
    '[Unit]',
    'Description=ee: nightly encrypted backup',
    '',
    '[Timer]',
    `OnCalendar=*-*-* ${hh}:${mm}:00 UTC`,
    'Persistent=true',
    '',
    '[Install]',
    'WantedBy=timers.target',
    '',
  ].join('\n')
}

/** Default before the owner sets a schedule: 03:<random minute> UTC. */
export function defaultSchedule(): { hour: number; minute: number } {
  return { hour: 3, minute: Math.floor(Math.random() * 60) }
}
